// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/**
 * @title BBRewardNodesConfig
 * @notice Static configuration of the 20 protocol-treasury wallets that receive
 *         equal shares of treasury-routed payouts (the BB-11 skipped-income
 *         fallback). Replaces the previous single `daoGovernor` wallet.
 *
 *         PRIVATE BY DESIGN. Addresses live in a separate file so they never
 *         appear in any public getter on the deployed vault. Edit this file
 *         BEFORE compile to set live addresses; do not commit the filled-in
 *         version to a public repository.
 *
 *         Naming follows DeFi protocol treasury convention:
 *           - 16 generic Reward Node wallets (NODE_0 .. NODE_15)
 *           -  1 protocolReserve   (operational reserve)
 *           -  1 insuranceFund     (coverage / shortfall buffer)
 *           -  1 bugBountyVault    (security bounty payouts)
 *           -  1 ecosystemFund     (integrations + grants)
 *
 *         Each wallet receives exactly 1/20 of any treasury-routed amount.
 */
library BBRewardNodesConfig {

    // ─── 16 Reward Node wallets (placeholders — replace before deploy) ──
    address internal constant NODE_0  = 0x0000000000000000000000000000000000001001;
    address internal constant NODE_1  = 0x0000000000000000000000000000000000001002;
    address internal constant NODE_2  = 0x0000000000000000000000000000000000001003;
    address internal constant NODE_3  = 0x0000000000000000000000000000000000001004;
    address internal constant NODE_4  = 0x0000000000000000000000000000000000001005;
    address internal constant NODE_5  = 0x0000000000000000000000000000000000001006;
    address internal constant NODE_6  = 0x0000000000000000000000000000000000001007;
    address internal constant NODE_7  = 0x0000000000000000000000000000000000001008;
    address internal constant NODE_8  = 0x0000000000000000000000000000000000001009;
    address internal constant NODE_9  = 0x0000000000000000000000000000000000001010;
    address internal constant NODE_10 = 0x0000000000000000000000000000000000001011;
    address internal constant NODE_11 = 0x0000000000000000000000000000000000001012;
    address internal constant NODE_12 = 0x0000000000000000000000000000000000001013;
    address internal constant NODE_13 = 0x0000000000000000000000000000000000001014;
    address internal constant NODE_14 = 0x0000000000000000000000000000000000001015;
    address internal constant NODE_15 = 0x0000000000000000000000000000000000001016;

    // ─── 4 DeFi-named treasury wallets ──────────────────────────────────
    address internal constant PROTOCOL_RESERVE  = 0x0000000000000000000000000000000000001017;
    address internal constant INSURANCE_FUND    = 0x0000000000000000000000000000000000001018;
    address internal constant BUG_BOUNTY_VAULT  = 0x0000000000000000000000000000000000001019;
    address internal constant ECOSYSTEM_FUND    = 0x0000000000000000000000000000000000001020;

    /// @notice Returns the 20 treasury wallets in fixed order. Used internally
    ///         by the vault during construction; not exposed via any public
    ///         getter on the deployed contract.
    function getNodes() internal pure returns (address[20] memory nodes) {
        nodes[0]  = NODE_0;
        nodes[1]  = NODE_1;
        nodes[2]  = NODE_2;
        nodes[3]  = NODE_3;
        nodes[4]  = NODE_4;
        nodes[5]  = NODE_5;
        nodes[6]  = NODE_6;
        nodes[7]  = NODE_7;
        nodes[8]  = NODE_8;
        nodes[9]  = NODE_9;
        nodes[10] = NODE_10;
        nodes[11] = NODE_11;
        nodes[12] = NODE_12;
        nodes[13] = NODE_13;
        nodes[14] = NODE_14;
        nodes[15] = NODE_15;
        nodes[16] = PROTOCOL_RESERVE;
        nodes[17] = INSURANCE_FUND;
        nodes[18] = BUG_BOUNTY_VAULT;
        nodes[19] = ECOSYSTEM_FUND;
    }
}

contracts/BBP_Storage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "./BBP_Types.sol";
import "./BBP_Constants.sol";
import "./BBP_PriceOracle.sol";
import "./BBP_RewardNodes.sol";
import "./interfaces/IERC20.sol";
import "./access/BBP_ReentrancyGuard.sol";

interface IPancakeRouter {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256, uint256, uint256);
}

/**
 * @title VaultStorage
 * @notice All state variables, mappings, and immutable addresses for BigBull V4
 * @dev Separated from logic for clarity and gas optimization
 *
 * IMMUTABLE WALLETS (set in constructor, cannot change):
 * - protocolFeeWallet: 5% USDT on deposits
 * - treasuryWallet: Genesis BIB payouts
 * - genesisWallet: Root team user
 * - daoGovernorWallet: Skipped Protocol Flow
 * - coldTreasury: Multisig for vault refills
 */

abstract contract VaultStorage is ReentrancyGuard, PriceOracle {

    // ═══════════════════════════════════════════════════════════════════════
    // IMMUTABLE WALLET ADDRESSES (5 wallets)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Genesis wallet - root team user with unlimited cap
    address public immutable genesisWallet;

    /// @notice Protocol-fee wallet - receives 5% USDT on every deposit
    address public immutable protocolFeeWallet;

    /// @notice Treasury wallet - receives BIB payouts for genesis
    address public immutable treasuryWallet;

    /// @notice Treasury node set (20 wallets). The BB-11 skipped-income
    ///         fallback is split equally across these 20 wallets (1/20 each).
    ///         INTERNAL visibility — accessible to the inheriting vault but
    ///         exposes NO public getter. Addresses are configured statically
    ///         in BBRewardNodesConfig.sol before compile.
    address[20] internal treasuryNodes;

    /// @notice Cold Treasury - holds majority BB tokens for refills (multisig)
    address public immutable coldTreasury;

    // ═══════════════════════════════════════════════════════════════════════
    // IMMUTABLE PROTOCOL ADDRESSES
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice PancakeSwap V2 Router
    IPancakeRouter public immutable router;

    /// @notice WBNB BSC mainnet address — hardcoded constant.
    /// @dev    Used only as a defensive blocklist entry in
    ///         `_requireNotSystemAddress` to prevent WBNB from being passed
    ///         as a referrer or appearing as a user account. The protocol
    ///         performs no swaps through WBNB (BB/USDT is the direct pair),
    ///         so this address is never moved by the vault. Hardcoded because
    ///         BSC WBNB is a fixed well-known address and the contract is
    ///         BSC-only by design.
    address internal constant WBNB_BSC = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;

    /// @notice DEAD address for LP burning
    address public constant DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    // ═══════════════════════════════════════════════════════════════════════
    // CORE MAPPINGS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice User team aggregate data
    mapping(address => VaultTypes.UserAccount) public users;

    /// @notice User's positions (multiple stakes)
    mapping(address => VaultTypes.Position[]) internal _positions;

    /// @notice Direct referrals of each user
    mapping(address => address[]) internal _directReferrals;

    /// @notice Direct referrer's index in their list (for O(1) lookup)
    mapping(address => uint256) internal _referrerIndex;

    /// @notice Daily deposit count per user (resets on new day)
    mapping(address => uint64) public lastDepositDay;
    mapping(address => uint16) public depositsToday;

    /// @notice User's personal stake limit (starts at 50, +25 per week)
    mapping(address => uint16) public personalStakeLimit;
    mapping(address => uint64) public lastStakeLimitIncrease;

    // ═══════════════════════════════════════════════════════════════════════
    // PROTOCOL STATS (Aggregate)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Total USDT ever deposited
    uint128 public totalDepositedUSD;

    /// @notice Total BB ever distributed
    uint128 public totalDistributedBB;

    /// @notice Total USDT paid to protocol-fee wallet
    uint128 public totalProtocolFeePaid;

    /// @notice Total amount sent to DAO Governor
    uint128 public totalDAOGovernorReceived;

    /// @notice Total amount in cold treasury (tracked)
    uint128 public totalRefilled;

    /// @notice Total enrolled users
    uint64 public totalUsers;

    /// @notice Total active positions
    uint64 public totalActivePositions;

    /// @notice Total stakes lifetime
    uint64 public totalStakesCreated;

    // ═══════════════════════════════════════════════════════════════════════
    // OWNER & EMERGENCY CONTROLS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Contract owner (renounceable)
    address public owner;

    /// @notice True after launch is finalized (renounces ownership permanently)
    bool public launchFinalized;

    /// @notice Emergency pause state
    bool public paused;

    /// @notice Anomaly detection auto-pause
    bool public anomalyPaused;

    /// @notice Emergency guardians (multisig members)
    mapping(address => bool) public guardians;

    /// @notice Generic addresses blocked from interacting with the protocol.
    /// @dev    Settable by any guardian at any time (no lock). Defense in depth
    ///         on top of token-level flashloan blocklist.
    mapping(address => bool) public isBlocked;
    uint8 public guardianCount;

    /// @notice Pending refill data
    struct PendingRefill {
        uint128 amount;
        uint64 unlockTime;
        bool executed;
    }
    PendingRefill public pendingRefill;

    /// @notice Refill tracking
    uint128 public refilledTodayAmount;
    uint64 public lastRefillDay;

    // ═══════════════════════════════════════════════════════════════════════
    // ANOMALY AUTO-PAUSE STATE (lightweight, gas-safe)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Packed claim-anomaly state (struct in VaultTypes).
    ///         Replaces the previous 7 individual variables to (a) enable passing
    ///         a storage ref to the external AnomalyMonitor library and (b)
    ///         reduce vault bytecode below EIP-170. Public getter is auto-
    ///         generated for backwards-compatible external reads.
    VaultTypes.ClaimAnomalyData public claimAnomaly;

    /// @notice Reason string for last auto-pause (for transparency)
    string public lastAnomalyReason;

    // ═══════════════════════════════════════════════════════════════════════
    // LEG / TEAM BUSINESS TRACKING (team plan core)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Per-user, per-direct-leg business volume (USD)
    ///         legBusinessUSD[user][directLegRoot] = total volume under that leg
    mapping(address => mapping(address => uint128)) public legBusinessUSD;

    // ═══════════════════════════════════════════════════════════════════════
    // ACHIEVER REGISTRIES (on-chain tracking only; rewards paid manually)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Achiever logs - newest entries appended at the end
    VaultTypes.Achiever[] public salaryAchievers;     // Performance Salary Bonus (2-leg)
    VaultTypes.Achiever[] public expansionAchievers;  // Performance Rewards (3-leg)
    VaultTypes.Achiever[] public lifestyleAchievers;  // Dream Lifestyle & Travel Rewards

    // ═══════════════════════════════════════════════════════════════════════
    // CLAIM CONTROL (global switch + per-wallet block for phishing/abuse)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Global claim switch (guardians can pause all claims independently
    ///         of the full emergency pause). Stakes/enroll remain unaffected.
    bool public claimsEnabled = true;

    /// @notice Wallets blocked from claiming (compromised / phishing / abusive).
    ///         Blocking does NOT seize funds; it only halts that wallet's claims.
    mapping(address => bool) public claimBlocked;

    // ═══════════════════════════════════════════════════════════════════════
    // PERFORMANCE REWARD QUEUE (one-time rewards released in 4 installments)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice FIFO queue of achieved performance rewards awaiting installment release
    mapping(address => VaultTypes.RewardGrant[]) public rewardQueue;

    /// @notice Index of the currently-processing grant in each user's queue
    mapping(address => uint256) public rewardQueueHead;

    /// @notice Per-user timestamp of last claimReward() call — enforces the
    ///         REWARD_CLAIM_COOLDOWN (24h) between consecutive claimReward calls.
    ///         Separate from CLAIM_COOLDOWN, so regular claims and reward claims have
    ///         independent timers.
    mapping(address => uint64) public lastRewardClaimAt;

    // ═══════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Deploy BigBull V4 vault with all immutable configuration
     * @dev All addresses validated and stored immutably - cannot change after deployment
     */
    constructor(
        VaultTypes.VaultConfig memory cfg,
        address[] memory guardians_
    )
        PriceOracle(cfg.pairAddress, cfg.bibToken, cfg.usdtToken)
    {
        // === ADDRESS VALIDATION ===

        if (cfg.router == address(0)) revert VaultTypes.ZeroAddress();
        if (cfg.genesis == address(0)) revert VaultTypes.ZeroAddress();
        if (cfg.protocolFee == address(0)) revert VaultTypes.ZeroAddress();
        if (cfg.treasury == address(0)) revert VaultTypes.ZeroAddress();
        if (cfg.coldTreasury == address(0)) revert VaultTypes.ZeroAddress();

        // === DUPLICATE WALLET CHECK ===

        if (cfg.genesis == cfg.protocolFee) revert VaultTypes.ZeroAddress();
        if (cfg.genesis == cfg.treasury) revert VaultTypes.ZeroAddress();
        if (cfg.genesis == cfg.coldTreasury) revert VaultTypes.ZeroAddress();
        if (cfg.protocolFee == cfg.treasury) revert VaultTypes.ZeroAddress();

        // === GENESIS — any non-zero wallet is allowed (EOA, multi-sig, AA, etc.) ===
        // Strict bytecode/extcodehash checks were removed because they broke
        // legitimate users on modern wallets (MetaMask Smart Account, Coinbase
        // Smart Wallet, Safe, Trust Wallet AA). The actual flash-loan attack
        // vector is contract-to-contract calls — blocked by tx.origin check on
        // enroll/stake/claim mutations in BigBullProtocol.

        // === STORE IMMUTABLES ===

        router = IPancakeRouter(cfg.router);

        genesisWallet = cfg.genesis;
        if (cfg.protocolFee == cfg.treasury) revert VaultTypes.ZeroAddress();
        if (cfg.genesis == cfg.coldTreasury) revert VaultTypes.ZeroAddress();
        if (cfg.protocolFee == cfg.coldTreasury) revert VaultTypes.ZeroAddress();
        if (cfg.treasury == cfg.coldTreasury) revert VaultTypes.ZeroAddress();

        protocolFeeWallet = cfg.protocolFee;
        treasuryWallet = cfg.treasury;
        coldTreasury = cfg.coldTreasury;

        // Initialize the 20-wallet treasury-node set from the static config file.
        // Addresses are baked in at compile time (BBRewardNodesConfig.sol) and
        // are NOT exposed via any public getter on the deployed vault.
        address[20] memory nodes = BBRewardNodesConfig.getNodes();
        for (uint256 i = 0; i < 20; ) {
            if (nodes[i] == address(0)) revert VaultTypes.ZeroAddress();
            treasuryNodes[i] = nodes[i];
            unchecked { ++i; }
        }

        owner = msg.sender;

        // === INITIALIZE GENESIS USER ===

        VaultTypes.UserAccount storage g = users[cfg.genesis];
        g.isEnrolled = true;
        g.enrolledAt = uint64(block.timestamp);
        g.firstDepositAt = uint64(block.timestamp);
        g.lastDepositAt = uint64(block.timestamp);
        g.amplifierWindowStart = uint64(block.timestamp);
        g.amplifierWindowEnd = uint64(block.timestamp) + VaultConstants.AMPLIFIER_WINDOW;

        // Genesis is the protected root - flag prevents re-achieve & staking
        g.isGenesis = true;

        // Genesis has all amplifiers from start (set once, never re-evaluated
        // because _checkAmplifier skips isGenesis users → no re-achieve bug)
        g.silverAchieved = true;
        g.goldAchieved = true;
        g.diamondAchieved = true;
        g.silverAchievedAt = uint64(block.timestamp);
        g.goldAchievedAt = uint64(block.timestamp);
        g.diamondAchievedAt = uint64(block.timestamp);

        // Logical seed deposit (not real USDT - genesis never stakes)
        g.totalDepositUSD = VaultConstants.ROOT_SEED_DEPOSIT;
        // Genesis cap starts at the unlimited sentinel; _ensureGenesisCap()
        // tops it back up if it ever gets drawn down, keeping it effectively
        // unlimited without overflow risk.
        g.currentCapUSD = VaultConstants.ROOT_MAX_CAP_USD;

        totalUsers = 1;
        personalStakeLimit[cfg.genesis] = VaultConstants.DEFAULT_STAKE_LIMIT;

        // === ANOMALY DEFAULTS ===
        // Single claim above $5,000 OR daily total above 3x average → auto-pause.
        // These are conservative starting values; guardians can tune pre-lock.
        claimAnomaly.singleClaimCeilingUSD = 5000e18;
        claimAnomaly.dailyClaimSpikeMult = 3;

        // === INITIALIZE GUARDIANS ===
        uint256 gLen = guardians_.length;
        if (gLen < 3 || gLen > 5) revert VaultTypes.ZeroAddress(); // Need 3-5 guardians
        for (uint256 i = 0; i < gLen; i++) {
            if (guardians_[i] == address(0)) revert VaultTypes.ZeroAddress();
            if (guardians[guardians_[i]]) revert VaultTypes.ZeroAddress(); // No duplicates
            guardians[guardians_[i]] = true;
        }
        guardianCount = uint8(gLen);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // BASIC GETTERS
    // ═══════════════════════════════════════════════════════════════════════

    function getPositionCount(address user) external view returns (uint256) {
        return _positions[user].length;
    }

    function getPosition(address user, uint256 id) external view returns (VaultTypes.Position memory) {
        if (id >= _positions[user].length) revert VaultTypes.InvalidPositionId();
        return _positions[user][id];
    }

    function getDirectsCount(address user) external view returns (uint256) {
        return _directReferrals[user].length;
    }

    function getDirect(address user, uint256 index) external view returns (address) {
        if (index >= _directReferrals[user].length) revert VaultTypes.InvalidPositionId();
        return _directReferrals[user][index];
    }

    function isGuardian(address account) external view returns (bool) {
        return guardians[account];
    }

    // ═══════════════════════════════════════════════════════════════════════
    // MODIFIERS
    // ═══════════════════════════════════════════════════════════════════════

    modifier onlyOwner() {
        if (msg.sender != owner) revert VaultTypes.UnauthorizedCaller();
        _;
    }

    modifier onlyGuardian() {
        if (!guardians[msg.sender]) revert VaultTypes.UnauthorizedCaller();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert VaultTypes.EmergencyActive();
        if (anomalyPaused) revert VaultTypes.EmergencyActive();
        _;
    }

    modifier onlyEOA() {
        // Block contract-to-contract calls only. Modern wallets (Smart Account,
        // multi-sig, AA) pass because tx.origin remains the user's signing EOA.
        if (msg.sender != tx.origin) revert VaultTypes.NotEOA();
        _;
    }

    modifier minGas() {
        if (gasleft() < VaultConstants.MIN_GAS_REQUIRED) {
            revert VaultTypes.InsufficientGas();
        }
        _;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // GENESIS PROTECTION HELPERS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Keep genesis cap effectively unlimited without overflow.
     * @dev Genesis earns from the tree but should never become "capped".
     *      If its remaining cap (capUSD - earnedUSD) ever falls below a
     *      threshold, top the cap back up to the sentinel. This avoids both
     *      (a) genesis getting stuck as capped, and (b) an unbounded number
     *      that could overflow uint128. Called on genesis claims.
     */
    function _ensureGenesisCap(address account) internal {
        VaultTypes.UserAccount storage u = users[account];
        if (!u.isGenesis) return;

        // If earned has consumed more than half the sentinel, reset the
        // baseline so remaining cap stays large but bounded.
        uint128 sentinel = VaultConstants.ROOT_MAX_CAP_USD;
        if (u.totalEarnedUSD > sentinel / 2) {
            // Re-anchor: capUSD = earnedUSD + full sentinel headroom
            // (capped to max uint128 to prevent overflow)
            uint256 newCap = uint256(u.totalEarnedUSD) + uint256(sentinel);
            if (newCap > type(uint128).max) {
                newCap = type(uint128).max;
            }
            u.currentCapUSD = uint128(newCap);
        }

        // Genesis can never be flagged capped
        u.isCapped = false;
    }
}

contracts/BBP_TestUSDT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/**
 * @title BBP_TestUSDT (tDT)
 * @notice Minimal BEP-20 test token used as the USDT stand-in for the
 *         Development variant of the BigBull protocol. Use this for the
 *         3-hour mainnet validation run with the tBB/tDT pair on PancakeSwap.
 *         DO NOT deploy on production — production uses real BSC-USDT
 *         at 0x55d398326f99059fF775485246999027B3197955.
 */
contract BBP_TestUSDT {
    string  public constant name = "BigBull Test USDT";
    string  public constant symbol = "tDT";
    uint8   public constant decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    address public owner;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    error NotOwner();
    error ZeroAddress();
    error InsufficientBalance();
    error InsufficientAllowance();

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(uint256 initialSupply) {
        owner = msg.sender;
        _mint(msg.sender, initialSupply * (10 ** uint256(decimals)));
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        if (spender == address(0)) revert ZeroAddress();
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            if (a < amount) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = a - amount; }
        }
        _transfer(from, to, amount);
        return true;
    }

    function _mint(address to, uint256 amount) private {
        if (to == address(0)) revert ZeroAddress();
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function _transfer(address from, address to, uint256 amount) private {
        if (to == address(0)) revert ZeroAddress();
        uint256 bal = balanceOf[from];
        if (bal < amount) revert InsufficientBalance();
        unchecked {
            balanceOf[from] = bal - amount;
            balanceOf[to] += amount;
        }
        emit Transfer(from, to, amount);
    }
}

contracts/BBP_Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/**
 * @title BigBullToken
 * @notice Fixed-supply BEP-20 token for the BigBull protocol.
 * @dev Security model (see docs/TOKEN_SECURITY.md for full rationale):
 *      - Fixed supply minted once in the constructor; no mint function exists.
 *      - One officialPair (BB/USDT, PancakeSwap V2). Buying from the pair is
 *        permanently blocked except for the single stakingContract address
 *        (the BigBull vault), which is set ONCE by the deployer and cannot
 *        ever change.
 *      - Transfers to/from any non-whitelisted contract revert (no secondary
 *        pools, no aggregator routes, no flash-swap exploit contracts).
 *      - Per-receive amount lock: every receipt of >= RECEIVE_LOCK_MIN_AMOUNT
 *        is independently locked for RECEIVE_LOCK seconds. Each amount unlocks
 *        on its own schedule; new receipts do not extend old locks. Defeats
 *        same-tx claim-and-sell flashloan attacks AND dust-griefing.
 *      - address(0) checked on every input; ERC-20 math uses Solidity 0.8.20
 *        built-in overflow checks (no SafeMath wrapper).
 *      - No selfdestruct, no delegatecall, no payable, no assembly-based
 *        balance edits, no owner ability to mint/burn/edit user balances.
 *      - Sell limits removed (was audit issue — replaced by per-receive lock).
 *      - Two-step ownership transfer + irreversible renounceOwnership gated
 *        on all configuration locks.
 */

interface IPairValidator {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IPancakeFactory {
    function getPair(address tokenA, address tokenB) external view returns (address);
}

contract BigBullToken {

    // ═══════════════════════════════════════════════════════════════════════
    // IMMUTABLE TOKEN METADATA
    // ═══════════════════════════════════════════════════════════════════════

    string  private _name;
    string  private _symbol;
    uint8   public  constant decimals = 18;
    uint256 public  immutable totalSupply;
    address public  immutable USDT;

    // ═══════════════════════════════════════════════════════════════════════
    // BALANCES & ALLOWANCES
    // ═══════════════════════════════════════════════════════════════════════

    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    // ═══════════════════════════════════════════════════════════════════════
    // OWNERSHIP (permanently locked to deployer — NO transfer, NO renounce)
    // ═══════════════════════════════════════════════════════════════════════
    //
    // `owner` is set exactly once in the constructor and is `immutable` at the
    // EVM level. Both `transferOwnership` and `renounceOwnership` are present
    // for ABI compatibility but always revert with OwnershipLocked. There is
    // no bypass and no upgrade path.
    //
    // Trade-off: if the owner key is ever lost, no future flashloan-provider
    // blocklist additions are possible. The deployer key must be kept offline
    // and recovered safely.

    address public immutable owner;

    // ═══════════════════════════════════════════════════════════════════════
    // PAIR & TRADING CONTROL
    // ═══════════════════════════════════════════════════════════════════════

    address public officialPair;
    bool    public pairLocked;
    bool    public tradingEnabled;
    uint256 public tradingEnabledBlock;
    uint256 public constant ANTISNIPE_BLOCKS = 3;

    /// @notice PancakeSwap V2 Factory on BSC mainnet. The official pair
    ///         MUST equal `factory.getPair(this, USDT)` — owner cannot set
    ///         any other address as the pair, even by mistake.
    address public constant PANCAKE_FACTORY = 0xcA143Ce32Fe78f1f7019d7d551a6402fC5350c73;

    /// @notice The ONLY address that can receive BB from the official pair.
    ///         Set once by the deployer (typically the BigBull vault). After
    ///         set, cannot change — gates the entire buy path.
    address public stakingContract;

    /// @notice General-purpose whitelist for the protocol's system contracts
    ///         (vault, router, configured operational wallets). Whitelisted
    ///         addresses bypass the receive-lock and contract-blocking rules.
    ///         The buy gate is independent (see stakingContract).
    mapping(address => bool) public isWhitelisted;
    bool public whitelistLocked;

    // ═══════════════════════════════════════════════════════════════════════
    // PER-RECEIVE LOCK QUEUE (anti-flashloan, anti-dust-grief)
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Duration each received amount is locked for.
    uint256 public constant RECEIVE_LOCK = 5 minutes;

    /// @notice Minimum amount that triggers a receive-lock entry.
    ///         Set to 1 wei — every non-zero receive is independently locked.
    ///         A separate 5-minute timer applies per amount.
    uint256 public constant RECEIVE_LOCK_MIN_AMOUNT = 1;

    /// @notice Maximum number of pending lock entries per address. Bounds
    ///         worst-case gas. When full, new receives still succeed but
    ///         do NOT get individually locked (the receive amount becomes
    ///         immediately spendable). Attacker cannot use this to drain
    ///         anyone — only the recipient's own protection is reduced.
    uint256 public constant MAX_PENDING_LOCKS = 50;

    struct ReceiveLockEntry {
        uint128 amount;     // BB amount locked (fits 1.7e20 BB = 170B BB ≫ supply)
        uint64  unlockAt;   // timestamp when this entry unlocks
    }

    mapping(address => ReceiveLockEntry[]) private _pendingLocks;

    // ═══════════════════════════════════════════════════════════════════════
    // FLASHLOAN-PROVIDER BLOCKLIST
    // ═══════════════════════════════════════════════════════════════════════

    mapping(address => bool) public isBlockedFlashloanProvider;

    // ═══════════════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════════════

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event OwnershipLockedForever(address indexed permanentOwner);
    event PairSet(address indexed pair);
    event PairLockedForever();
    event TradingEnabled(uint256 blockNumber);
    event StakingContractSet(address indexed stakingContract);
    event WhitelistUpdated(address indexed account, bool status);
    event WhitelistLockedForever();
    event FlashloanProviderUpdated(address indexed provider, bool blocked);
    event ReceiveLockAdded(address indexed account, uint128 amount, uint64 unlockAt);

    // ═══════════════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════════════

    error ZeroAddress();
    error ZeroAmount();
    error InsufficientBalance();
    error InsufficientAllowance();
    error InsufficientUnlocked();        // tried to move locked tokens
    error NotOwner();
    error OwnershipLocked();
    error NotAContract();
    error TradingNotEnabled();
    error TradingAlreadyEnabled();
    error BuyingBlocked();
    error BlockedContract();
    error PairAlreadySet();
    error PairIsLocked();
    error WhitelistIsLocked();
    error InvalidPair();
    error SamePair();
    error SnipeBlocked();
    error StakingContractAlreadySet();
    error FlashloanProviderBlocked();

    // ═══════════════════════════════════════════════════════════════════════
    // MODIFIERS
    // ═══════════════════════════════════════════════════════════════════════

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════════════

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 supply_,
        address usdt_
    ) {
        if (usdt_ == address(0)) revert ZeroAddress();
        if (supply_ == 0) revert ZeroAmount();

        _name = name_;
        _symbol = symbol_;
        USDT = usdt_;

        uint256 supplyWithDecimals = supply_ * (10 ** uint256(decimals));
        totalSupply = supplyWithDecimals;
        owner = msg.sender;
        emit OwnershipLockedForever(msg.sender);
        _balances[msg.sender] = supplyWithDecimals;
        isWhitelisted[msg.sender] = true;

        emit Transfer(address(0), msg.sender, supplyWithDecimals);
        emit WhitelistUpdated(msg.sender, true);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ERC-20 VIEWS
    // ═══════════════════════════════════════════════════════════════════════

    function name() external view returns (string memory) { return _name; }
    function symbol() external view returns (string memory) { return _symbol; }
    function balanceOf(address account) external view returns (uint256) { return _balances[account]; }
    function allowance(address owner_, address spender) external view returns (uint256) {
        return _allowances[owner_][spender];
    }

    /**
     * @notice Sum of all RECEIVED amounts still inside their 5-minute lock
     *         window. The unlocked portion is `balanceOf - lockedBalance`.
     */
    function lockedBalance(address account) public view returns (uint256 locked) {
        if (isWhitelisted[account]) return 0;
        ReceiveLockEntry[] storage locks = _pendingLocks[account];
        uint256 nowT = block.timestamp;
        uint256 len = locks.length;
        for (uint256 i = 0; i < len; ) {
            if (locks[i].unlockAt > nowT) locked += locks[i].amount;
            unchecked { ++i; }
        }
    }

    function unlockedBalance(address account) external view returns (uint256) {
        uint256 bal = _balances[account];
        uint256 locked = lockedBalance(account);
        return bal > locked ? bal - locked : 0;
    }

    function pendingLockCount(address account) external view returns (uint256) {
        return _pendingLocks[account].length;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ERC-20 WRITE
    // ═══════════════════════════════════════════════════════════════════════

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        _spendAllowance(from, msg.sender, amount);
        _transfer(from, to, amount);
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue) external returns (bool) {
        if (spender == address(0)) revert ZeroAddress();
        uint256 currentAllowance = _allowances[msg.sender][spender];
        _approve(msg.sender, spender, currentAllowance + addedValue);
        return true;
    }

    function decreaseAllowance(address spender, uint256 subtractedValue) external returns (bool) {
        if (spender == address(0)) revert ZeroAddress();
        uint256 currentAllowance = _allowances[msg.sender][spender];
        if (currentAllowance < subtractedValue) revert InsufficientAllowance();
        unchecked {
            _approve(msg.sender, spender, currentAllowance - subtractedValue);
        }
        return true;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // CORE TRANSFER LOGIC
    // ═══════════════════════════════════════════════════════════════════════

    function _transfer(address from, address to, uint256 amount) internal {
        if (from == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();

        uint256 fromBalance = _balances[from];
        if (fromBalance < amount) revert InsufficientBalance();

        bool fromWL = isWhitelisted[from];
        bool toWL   = isWhitelisted[to];

        // ── 1. WHITELIST FAST-PATH ──────────────────────────────────────────
        // Whitelisted parties (vault, deployer pre-lock, configured wallets)
        // bypass all rules EXCEPT the structural buy block, which is checked
        // first below.
        if (from == officialPair) {
            // ── 2. BUY GATE — only stakingContract may receive ──────────────
            // No whitelist exception. The single stakingContract is the
            // ONLY address that can ever receive BB from the pair (set once,
            // locked from the moment of set). Defeats any path to public buy.
            if (to != stakingContract) revert BuyingBlocked();
            _rawTransfer(from, to, amount);
            return;
        }

        if (fromWL || toWL) {
            // Sending FROM a whitelisted address (vault → user during claim)
            // OR sending TO a whitelisted address (deposits to vault).
            _rawTransfer(from, to, amount);
            return;
        }

        // ── 3. PER-RECEIVE LOCK ENFORCEMENT ─────────────────────────────────
        // The sender must leave at least `lockedBalance(from)` BB in their
        // account after the transfer. This means every locked entry stays
        // locked until its own unlockAt, regardless of new activity.
        _purgeExpiredLocks(from);
        uint256 stillLocked = _sumLocked(from);
        if (fromBalance - amount < stillLocked) revert InsufficientUnlocked();

        // ── 4. FLASHLOAN-PROVIDER BLOCKLIST ─────────────────────────────────
        if (from != officialPair && to != officialPair) {
            if (isBlockedFlashloanProvider[from] || isBlockedFlashloanProvider[to]) {
                revert FlashloanProviderBlocked();
            }
        }

        // ── 5. TRADING GATE ─────────────────────────────────────────────────
        if (!tradingEnabled) revert TradingNotEnabled();

        bool toPair = (to == officialPair);

        // ── 6. SINGLE-PAIR ENFORCEMENT ──────────────────────────────────────
        if (!toPair && _isContract(to))   revert BlockedContract();
        if (_isContract(from))            revert BlockedContract();

        // ── 7. ANTI-SNIPE (sells in first ANTISNIPE_BLOCKS) ─────────────────
        if (toPair && block.number <= tradingEnabledBlock + ANTISNIPE_BLOCKS) {
            revert SnipeBlocked();
        }

        _rawTransfer(from, to, amount);
    }

    function _rawTransfer(address from, address to, uint256 amount) private {
        uint256 fromBalance = _balances[from];
        unchecked {
            _balances[from] = fromBalance - amount;
            _balances[to] += amount;
        }
        // Per-receive lock: add an entry for EVERY non-zero receipt to a
        // non-whitelisted recipient. Each amount gets its own independent
        // 5-minute timer; no dust exemption. After 5 minutes the recipient
        // can transfer / approve / swap that amount.
        if (!isWhitelisted[to] && amount > 0) {
            _addLockEntry(to, amount);
        }
        emit Transfer(from, to, amount);
    }

    function _approve(address owner_, address spender, uint256 amount) private {
        if (owner_ == address(0)) revert ZeroAddress();
        if (spender == address(0)) revert ZeroAddress();
        _allowances[owner_][spender] = amount;
        emit Approval(owner_, spender, amount);
    }

    function _spendAllowance(address owner_, address spender, uint256 amount) private {
        uint256 currentAllowance = _allowances[owner_][spender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < amount) revert InsufficientAllowance();
            unchecked {
                _approve(owner_, spender, currentAllowance - amount);
            }
        }
    }

    function _isContract(address account) private view returns (bool) {
        return account.code.length > 0;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // RECEIVE-LOCK INTERNAL HELPERS
    // ═══════════════════════════════════════════════════════════════════════

    function _addLockEntry(address account, uint256 amount) private {
        ReceiveLockEntry[] storage locks = _pendingLocks[account];
        // Opportunistically purge expired entries before pushing — keeps queue
        // bounded under normal use.
        _purgeExpiredLocks(account);
        // If still at max after purge, silently skip the lock (recipient loses
        // protection on this particular receipt, but cannot be DoS'd).
        if (locks.length >= MAX_PENDING_LOCKS) return;
        uint64 unlockAt = uint64(block.timestamp + RECEIVE_LOCK);
        locks.push(ReceiveLockEntry({ amount: uint128(amount), unlockAt: unlockAt }));
        emit ReceiveLockAdded(account, uint128(amount), unlockAt);
    }

    function _purgeExpiredLocks(address account) private {
        ReceiveLockEntry[] storage locks = _pendingLocks[account];
        uint256 len = locks.length;
        if (len == 0) return;
        uint256 nowT = block.timestamp;
        uint256 writeIdx = 0;
        for (uint256 i = 0; i < len; ) {
            if (locks[i].unlockAt > nowT) {
                if (writeIdx != i) locks[writeIdx] = locks[i];
                unchecked { ++writeIdx; }
            }
            unchecked { ++i; }
        }
        while (locks.length > writeIdx) locks.pop();
    }

    function _sumLocked(address account) private view returns (uint256 locked) {
        ReceiveLockEntry[] storage locks = _pendingLocks[account];
        uint256 len = locks.length;
        for (uint256 i = 0; i < len; ) {
            locked += locks[i].amount;
            unchecked { ++i; }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // PAIR MANAGEMENT
    // ═══════════════════════════════════════════════════════════════════════

    function setOfficialPair(address pair_) external onlyOwner {
        _setOfficialPair(pair_);
    }

    function _setOfficialPair(address pair_) private {
        if (pairLocked) revert PairIsLocked();
        if (pair_ == address(0)) revert ZeroAddress();
        if (pair_ == officialPair) revert SamePair();
        if (!_validatePair(pair_)) revert InvalidPair();

        // STRICT factory verification — the candidate pair MUST be the exact
        // address returned by `factory.getPair(this, USDT)`. This prevents
        // the owner from ever locking-in a non-canonical pair (e.g. a
        // hand-crafted contract that mimics the IPancakePair ABI). The
        // factory result is deterministic — if no pair exists yet, this
        // returns address(0) and reverts here, forcing the deployer to
        // create the pair via `factory.createPair(this, USDT)` first.
        address expected = IPancakeFactory(PANCAKE_FACTORY).getPair(address(this), USDT);
        if (pair_ != expected || expected == address(0)) revert InvalidPair();

        officialPair = pair_;
        emit PairSet(pair_);
    }

    /**
     * @notice Atomic set + lock — strongly recommended over the two-step path.
     */
    function setAndLockPair(address pair_) external onlyOwner {
        _setOfficialPair(pair_);
        pairLocked = true;
        emit PairLockedForever();
    }

    function lockPair() external onlyOwner {
        if (officialPair == address(0)) revert InvalidPair();
        if (pairLocked) revert PairIsLocked();
        pairLocked = true;
        emit PairLockedForever();
    }

    function _validatePair(address pair_) private view returns (bool) {
        try IPairValidator(pair_).token0() returns (address t0) {
            try IPairValidator(pair_).token1() returns (address t1) {
                bool hasThis = (t0 == address(this)) || (t1 == address(this));
                bool hasUSDT = (t0 == USDT) || (t1 == USDT);
                return hasThis && hasUSDT;
            } catch { return false; }
        } catch { return false; }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // STAKING CONTRACT (one-time, gates the entire buy path)
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Set the single contract address allowed to receive BB from the
     *         official pair. Can ONLY be called once. After set, no admin
     *         function exists to change it — the buy gate is permanently
     *         bound to this address.
     * @dev    Use a Gnosis Safe multisig as the deployer when calling this.
     */
    function setStakingContract(address contract_) external onlyOwner {
        if (stakingContract != address(0)) revert StakingContractAlreadySet();
        if (contract_ == address(0)) revert ZeroAddress();
        if (contract_.code.length == 0) revert NotAContract();
        stakingContract = contract_;
        emit StakingContractSet(contract_);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // WHITELIST MANAGEMENT
    // ═══════════════════════════════════════════════════════════════════════

    function setWhitelist(address account, bool status) external onlyOwner {
        if (whitelistLocked) revert WhitelistIsLocked();
        if (account == address(0)) revert ZeroAddress();
        isWhitelisted[account] = status;
        emit WhitelistUpdated(account, status);
    }

    function setWhitelistBatch(address[] calldata accounts, bool status) external onlyOwner {
        if (whitelistLocked) revert WhitelistIsLocked();
        uint256 len = accounts.length;
        for (uint256 i = 0; i < len; ) {
            address acct = accounts[i];
            if (acct == address(0)) revert ZeroAddress();
            isWhitelisted[acct] = status;
            emit WhitelistUpdated(acct, status);
            unchecked { ++i; }
        }
    }

    function lockWhitelist() external onlyOwner {
        whitelistLocked = true;
        emit WhitelistLockedForever();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // TRADING TOGGLE (one-way: off → on)
    // ═══════════════════════════════════════════════════════════════════════

    function enableTrading() external onlyOwner {
        if (tradingEnabled) revert TradingAlreadyEnabled();
        if (officialPair == address(0)) revert InvalidPair();
        tradingEnabled = true;
        tradingEnabledBlock = block.number;
        emit TradingEnabled(block.number);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // FLASHLOAN BLOCKLIST
    // ═══════════════════════════════════════════════════════════════════════

    function setFlashloanProvider(address provider, bool blocked) external onlyOwner {
        if (provider == address(0)) revert ZeroAddress();
        if (provider == officialPair) revert InvalidPair();
        if (provider.code.length == 0) revert NotAContract(); // token blocklist: contracts only
        isBlockedFlashloanProvider[provider] = blocked;
        emit FlashloanProviderUpdated(provider, blocked);
    }

    function setFlashloanProviderBatch(address[] calldata providers, bool blocked) external onlyOwner {
        uint256 len = providers.length;
        for (uint256 i = 0; i < len; ) {
            address p = providers[i];
            if (p == address(0)) revert ZeroAddress();
            if (p == officialPair) revert InvalidPair();
            isBlockedFlashloanProvider[p] = blocked;
            emit FlashloanProviderUpdated(p, blocked);
            unchecked { ++i; }
        }
    }


    // ═══════════════════════════════════════════════════════════════════════
    // OWNERSHIP — PERMANENTLY LOCKED
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Ownership transfer is NOT supported. Always reverts.
     * @dev Provided only for ABI compatibility — there is no way to change
     *      the owner after construction. The `owner` storage slot is
     *      `immutable` and cannot be modified at the EVM level.
     */
    function transferOwnership(address /* newOwner */) external pure {
        revert OwnershipLocked();
    }

    /**
     * @notice Ownership renouncement is NOT supported. Always reverts.
     * @dev The deployer retains ownership permanently to enable ongoing
     *      flashloan-provider blocklist additions as new attack vectors
     *      emerge. All other admin powers (pair, whitelist, sell rules)
     *      ARE permanently lockable via their respective lock functions.
     */
    function renounceOwnership() external pure {
        revert OwnershipLocked();
    }
}

