// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "../interfaces/IERC20.sol";
import "./SafeERC20.sol";

/**
 * @title SafeTransferLib (thin adapter over OpenZeppelin SafeERC20 v5.4.0)
 * @notice This library is a backward-compatibility shim. All logic delegates to
 *         the EXACT OpenZeppelin v5.4.0 SafeERC20 implementation. It exists so
 *         existing call sites in the protocol can continue calling the
 *         address-based API (`USDT_TOKEN.safeTransferFrom(...)`) without a
 *         large refactor.
 *
 *         All transfer/approval safety guarantees come from OpenZeppelin:
 *           - Assembly-based low-level call (memory-safe)
 *           - Optional-return handling (tokens that return nothing on success)
 *           - SafeERC20FailedOperation revert on any failure
 *           - forceApprove handles USDT-style non-zero -> non-zero rejection
 *             by resetting to 0 then re-approving
 *
 *         Do NOT add new logic here — extend SafeERC20.sol directly if needed.
 */
library SafeTransferLib {
    using SafeERC20 for IERC20;

    /// @notice Wrapper-only helper for explicit pre-checks (allowance & balance).
    function _allowance(address token, address owner, address spender) internal view returns (uint256) {
        return IERC20(token).allowance(owner, spender);
    }

    function _balanceOf(address token, address account) internal view returns (uint256) {
        return IERC20(token).balanceOf(account);
    }

    /// @notice Reverts on failure. Handles tokens that return no value.
    function safeTransfer(address token, address to, uint256 amount) internal {
        IERC20(token).safeTransfer(to, amount);
    }

    /// @notice Reverts on failure. Handles tokens that return no value.
    function safeTransferFrom(address token, address from, address to, uint256 amount) internal {
        IERC20(token).safeTransferFrom(from, to, amount);
    }

    /// @notice Approve `spender` to spend `amount`. Uses OpenZeppelin's
    ///         `forceApprove`, which automatically falls back to a 0-reset
    ///         + re-approve sequence when a non-zero allowance is already set
    ///         (the classic USDT pattern).
    function safeApprove(address token, address spender, uint256 amount) internal {
        IERC20(token).forceApprove(spender, amount);
    }
}

contracts/libraries/BBP_SecurityGuards.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "../BBP_Types.sol";
import "../BBP_Constants.sol";

/**
 * @title SecurityGuards
 * @notice Additional security layer for BigBull V4
 * @dev Critical security checks beyond basic validations
 *
 * COVERAGE:
 * - Chain ID verification (BSC mainnet only)
 * - Anomaly detection thresholds
 * - Triple-layer token verification
 * - Rate limit guards
 * - Wallet impersonation detection
 * - Bytecode integrity checks
 */

library SecurityGuards {

    // ═══════════════════════════════════════════════════════════════════════
    // CHAIN ID VERIFICATION
    // ═══════════════════════════════════════════════════════════════════════

    uint256 internal constant BSC_MAINNET_CHAIN_ID = 56;
    uint256 internal constant BSC_TESTNET_CHAIN_ID = 97;

    error WrongChain();
    error AnomalyDetected();
    error ImpersonationAttempt();
    error TokenMismatch();
    error InvalidTimestamp();
    error AmountSuspicious();
    error RateLimitExceeded();

    /**
     * @notice Verify current chain is BSC mainnet (or testnet for dev)
     */
    function validateChain() internal view {
        uint256 chainId = block.chainid;
        if (chainId != BSC_MAINNET_CHAIN_ID && chainId != BSC_TESTNET_CHAIN_ID) {
            revert WrongChain();
        }
    }

    /**
     * @notice Strict mainnet-only check
     */
    function validateMainnetOnly() internal view {
        if (block.chainid != BSC_MAINNET_CHAIN_ID) revert WrongChain();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // TIMESTAMP VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Validate block timestamp is reasonable
     * @dev Prevents manipulation attacks
     */
    function validateTimestamp(uint64 timestamp) internal view {
        // Must not be in the future (5 second tolerance for clock skew)
        if (timestamp > block.timestamp + 5) revert InvalidTimestamp();
        // Must not be too far in the past (24h tolerance)
        if (timestamp < block.timestamp - 86400) revert InvalidTimestamp();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ADDRESS VERIFICATION
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Multi-layer address verification
     */
    function validateAddress(address addr) internal pure {
        if (addr == address(0)) revert VaultTypes.ZeroAddress();
        // Burn addresses
        if (addr == address(0x000000000000000000000000000000000000dEaD)) revert VaultTypes.ZeroAddress();
        if (addr == address(0x0000000000000000000000000000000000000001)) revert VaultTypes.ZeroAddress();
    }

    /**
     * @notice Triple-layer EOA verification
     */
    function validateEOAStrict(address user) internal view {
        // Layer 1: tx.origin match
        if (user != tx.origin) revert ImpersonationAttempt();

        // Layer 2: No bytecode
        if (user.code.length != 0) revert ImpersonationAttempt();

        // Layer 3: extcodehash check (EIP-7702 detection)
        bytes32 codeHash;
        assembly {
            codeHash := extcodehash(user)
        }
        bytes32 EMPTY_HASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;
        if (codeHash != bytes32(0) && codeHash != EMPTY_HASH) {
            revert ImpersonationAttempt();
        }

        // Layer 4: Check balance is reasonable (not contract-like)
        // EOAs typically don't have huge balances or be zero
        // (skip strict check, but log suspicious)
    }

    // ═══════════════════════════════════════════════════════════════════════
    // TOKEN VERIFICATION
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Verify token transfer happened correctly
     * @dev Tracks balance before/after to confirm actual transfer
     */
    function verifyTokenTransfer(
        uint256 balanceBefore,
        uint256 balanceAfter,
        uint256 expectedAmount
    ) internal pure {
        if (balanceAfter < balanceBefore) revert TokenMismatch();
        uint256 actualReceived = balanceAfter - balanceBefore;

        // Must receive at least 99% (allow for fee-on-transfer tokens)
        uint256 minExpected = (expectedAmount * 99) / 100;
        if (actualReceived < minExpected) revert TokenMismatch();
    }

    /**
     * @notice Verify token addresses match expected
     */
    function verifyTokenAddress(
        address received,
        address expected
    ) internal pure {
        if (received != expected) revert TokenMismatch();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ANOMALY DETECTION
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Check if claim amount is anomalous compared to recent average
     * @param attemptUSD Amount being claimed
     * @param avgDailyClaimUSD Recent average daily claims
     * @return suspicious True if claim is anomalous
     */
    function detectClaimAnomaly(
        uint128 attemptUSD,
        uint128 avgDailyClaimUSD
    ) internal pure returns (bool suspicious) {
        if (avgDailyClaimUSD == 0) return false;

        // 3x the average = suspicious
        return attemptUSD > (avgDailyClaimUSD * 3);
    }

    /**
     * @notice Check if liquidity drop is anomalous
     */
    function detectLiquidityAnomaly(
        uint128 currentReserve,
        uint128 previousReserve
    ) internal pure returns (bool suspicious) {
        if (previousReserve == 0) return false;
        if (currentReserve >= previousReserve) return false;

        // 30% drop in single check = suspicious
        uint128 drop = previousReserve - currentReserve;
        uint256 dropPercent = (uint256(drop) * 100) / uint256(previousReserve);

        return dropPercent > 30;
    }

    /**
     * @notice Detect price manipulation by deviation
     */
    function detectPriceAnomaly(
        uint128 spotPrice,
        uint128 twapPrice,
        uint16 maxDeviationBP
    ) internal pure returns (bool suspicious) {
        if (twapPrice == 0 || spotPrice == 0) return false;

        uint256 deviation;
        if (spotPrice > twapPrice) {
            deviation = ((uint256(spotPrice) - uint256(twapPrice)) * 10000) / uint256(twapPrice);
        } else {
            deviation = ((uint256(twapPrice) - uint256(spotPrice)) * 10000) / uint256(twapPrice);
        }

        return deviation > maxDeviationBP;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // RATE LIMITING
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Check per-block global rate limit
     */
    function checkBlockRateLimit(
        uint128 blockTotal,
        uint128 blockLimit
    ) internal pure {
        if (blockTotal >= blockLimit) revert RateLimitExceeded();
    }

    /**
     * @notice Check hourly rate limit
     */
    function checkHourlyRateLimit(
        uint128 hourlyTotal,
        uint128 hourlyLimit
    ) internal pure {
        if (hourlyTotal >= hourlyLimit) revert RateLimitExceeded();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // SUSPICIOUS PATTERN DETECTION
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Detect suspicious deposit pattern (multiple deposits same block)
     */
    function detectDepositPattern(
        uint64 lastDepositBlock,
        uint16 depositsInSameBlock
    ) internal view returns (bool suspicious) {
        if (lastDepositBlock != uint64(block.number)) return false;
        return depositsInSameBlock >= 3;
    }

    /**
     * @notice Detect referral tree spam (multiple enrolls under same referrer fast)
     */
    function detectTreeSpam(
        uint64 lastEnrollTime,
        uint64 currentTime,
        uint16 enrollsInWindow
    ) internal pure returns (bool suspicious) {
        // 5 enrolls within 60 seconds = spam
        if (currentTime - lastEnrollTime > 60) return false;
        return enrollsInWindow >= 5;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // GAS GRIEFING PROTECTION
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Verify enough gas remains for safe execution
     */
    function requireMinGas(uint256 minRequired) internal view {
        if (gasleft() < minRequired) revert VaultTypes.InsufficientGas();
    }

    /**
     * @notice Check gas isn't being manipulated (block gas limit)
     */
    function validateGasContext() internal view {
        // Block gas limit should be reasonable for BSC
        // BSC block gas limit: ~140M
        if (block.gaslimit < 30_000_000) revert VaultTypes.InsufficientGas();
    }
}

contracts/libraries/BBP_TeamTierLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "../BBP_Types.sol";
import "./BBP_DistributionLib.sol";
import "./BBP_AmplifierLib.sol";

/**
 * @title TeamTierLib
 * @notice External (delegatecall) library holding the heavy leg-business
 *         tracking and tier-achievement detection logic.
 * @dev Marked `public` so it deploys as a SEPARATE contract and is called via
 *      delegatecall — this keeps the main vault bytecode small (under 24KB).
 *      Executes in the vault's storage context, so storage references are valid.
 *
 *      On-chain it ONLY tracks achievements (records who reached which tier and
 *      when). All salary / reward / lifestyle payouts are handled manually
 *      off-chain, exactly as the plan specifies.
 */
library TeamTierLib {

    event SalaryTierAchieved(address indexed user, uint8 tier, uint256 timestamp);
    event ExpansionTierAchieved(address indexed user, uint8 tier, uint256 timestamp);
    event LifestyleTierAchieved(address indexed user, uint8 tier, uint256 timestamp);
    event RewardQueued(address indexed user, uint8 tier, uint128 totalUSD);

    /**
     * @notice Update one upline's leg volumes and detect newly achieved tiers.
     * @param legBusinessUSD storage mapping: user => directLegRoot => volume
     * @param salaryAchievers storage log of salary achievers
     * @param expansionAchievers storage log of expansion achievers
     * @param lifestyleAchievers storage log of lifestyle achievers
     * @param u the upline's account record (storage)
     * @param upline the upline address
     * @param child the direct-leg root the volume flowed through
     * @param amount the staked amount (USD)
     */
    /**
     * @notice Walk up to 50 uplines from a staker, building team volume and
     *         updating leg/tier tracking for each. Moves the whole loop off the
     *         vault to save vault bytecode.
     */
    function distributeTeamVolume(
        mapping(address => VaultTypes.UserAccount) storage users,
        mapping(address => mapping(address => uint128)) storage legBusinessUSD,
        VaultTypes.Achiever[] storage salaryAchievers,
        VaultTypes.Achiever[] storage expansionAchievers,
        VaultTypes.Achiever[] storage lifestyleAchievers,
        mapping(address => VaultTypes.RewardGrant[]) storage rewardQueue,
        address staker,
        uint128 amount
    ) public {
        address child = staker;
        address current = users[staker].referrer;
        for (uint8 level = 1; level <= 50 && current != address(0); ) {
            VaultTypes.UserAccount storage u = users[current];
            u.teamVolumeUSD += amount;
            updateLegAndTiers(
                legBusinessUSD,
                salaryAchievers,
                expansionAchievers,
                lifestyleAchievers,
                rewardQueue[current],
                u,
                current,
                child,
                amount
            );
            child = current;
            current = u.referrer;
            unchecked { ++level; }
        }
    }

    function updateLegAndTiers(
        mapping(address => mapping(address => uint128)) storage legBusinessUSD,
        VaultTypes.Achiever[] storage salaryAchievers,
        VaultTypes.Achiever[] storage expansionAchievers,
        VaultTypes.Achiever[] storage lifestyleAchievers,
        VaultTypes.RewardGrant[] storage rewardQueue,
        VaultTypes.UserAccount storage u,
        address upline,
        address child,
        uint128 amount
    ) public {
        // Update this leg's running volume
        uint128 newLegVol = legBusinessUSD[upline][child] + amount;
        legBusinessUSD[upline][child] = newLegVol;

        // Maintain top-2 legs in O(1)
        if (child == u.strongestLegRoot) {
            u.strongestLegUSD = newLegVol;
        } else if (newLegVol > u.strongestLegUSD) {
            u.secondLegRoot = u.strongestLegRoot;
            u.secondLegUSD = u.strongestLegUSD;
            u.strongestLegRoot = child;
            u.strongestLegUSD = newLegVol;
        } else if (child == u.secondLegRoot) {
            u.secondLegUSD = newLegVol;
        } else if (newLegVol > u.secondLegUSD) {
            u.secondLegRoot = child;
            u.secondLegUSD = newLegVol;
        }

        // Compute leg figures
        uint128 legA = u.strongestLegUSD;
        uint128 legB = u.teamVolumeUSD - legA;            // all other legs
        uint128 leg2 = u.secondLegUSD;
        uint128 leg3 = legB > leg2 ? (legB - leg2) : 0;   // remainder beyond top-2

        // SALARY (2-leg)
        uint8 ns = DistributionLib.advanceSalaryTier(legA, legB, u.highestPerformanceRank);
        if (ns > u.highestPerformanceRank) {
            // Start the salary stream checkpoint on first rank, so salary only
            // accrues from achievement time forward (never retroactively).
            if (u.lastSalaryAccrualTime == 0) {
                u.lastSalaryAccrualTime = uint64(block.timestamp);
            }
            u.highestPerformanceRank = ns;
            u.currentPerformanceRank = ns;
            salaryAchievers.push(VaultTypes.Achiever(upline, ns, uint64(block.timestamp)));
            emit SalaryTierAchieved(upline, ns, block.timestamp);

            // Booster: gaining a salary rank within the 100-day window raises the
            // amplifier (extends ROI cap + daily rate) for this upline's stakes.
            AmplifierLib.applyBooster(u, uint64(block.timestamp));
        }

        // EXPANSION (3-leg) — queue a one-time reward grant per crossed tier.
        // Each grant is released later in 4 installments (6h apart) via claimReward.
        uint8 ne = DistributionLib.advanceExpansionTier(legA, leg2, leg3, u.highestExpansionTier);
        if (ne > u.highestExpansionTier) {
            for (uint8 t = u.highestExpansionTier + 1; t <= ne; ) {
                uint128 reward = DistributionLib.expansionRewardOf(t);
                if (reward > 0) {
                    rewardQueue.push(VaultTypes.RewardGrant(t, reward, 0, uint64(block.timestamp)));
                    emit RewardQueued(upline, t, reward);
                }
                unchecked { ++t; }
            }
            u.highestExpansionTier = ne;
            expansionAchievers.push(VaultTypes.Achiever(upline, ne, uint64(block.timestamp)));
            emit ExpansionTierAchieved(upline, ne, block.timestamp);
        }

        // LIFESTYLE (2-leg)
        uint8 nl = DistributionLib.advanceLifestyleTier(legA, legB, u.lifestyleAchieved);
        if (nl > u.lifestyleAchieved) {
            u.lifestyleAchieved = nl;
            lifestyleAchievers.push(VaultTypes.Achiever(upline, nl, uint64(block.timestamp)));
            emit LifestyleTierAchieved(upline, nl, block.timestamp);
        }
    }
}

contracts/libraries/BBP_ValidationLib.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "./../BBP_Types.sol";
import "./../BBP_Constants.sol";

/**
 * @title ValidationLib
 * @notice All security checks and validation logic
 * @dev Only enforces tx.origin == msg.sender so smart-account / multi-sig
 *      wallets (MetaMask Smart Account, Coinbase Smart Wallet, Trust Wallet AA,
 *      Safe, etc.) work normally. Blocks ONLY contract-to-contract calls into
 *      enroll/stake/claim — which is the actual attack vector (flash loan bots
 *      that try to mass-register fake users in a single transaction).
 */
library ValidationLib {

    // ═══════════════════════════════════════════════════════════════════════
    // EOA / CONTRACT CHECKS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Block contracts (incl. flash-loan attackers) from calling
     *         protocol-mutating functions. Modern wallets (Smart Account,
     *         AA, multi-sig) pass this check because tx.origin is still the
     *         user's EOA — even when their wallet delegates calls.
     */
    function validateEOA(address user) internal view {
        if (user != tx.origin) revert VaultTypes.NotEOA();
    }

    /**
     * @notice Validate an externally-provided address parameter (referrer,
     *         genesis, etc). Only check it isn't zero. Modern wallet contracts
     *         and smart wallets are valid users — do not block them.
     */
    function validateEOAExternal(address user) internal pure {
        if (user == address(0)) revert VaultTypes.ZeroAddress();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // DEPOSIT VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    function validateDepositAmount(uint128 amount) internal pure {
        if (amount < VaultConstants.MIN_DEPOSIT) revert VaultTypes.MinDepositNotMet();
        if (amount > VaultConstants.MAX_DEPOSIT) revert VaultTypes.MaxDepositExceeded();
        if (amount % 1e18 != 0) revert VaultTypes.InvalidAmount();
    }

    function validateDailyDepositLimit(
        uint64 lastDay,
        uint16 todayCount,
        uint64 currentTime
    ) internal pure returns (uint16 newCount, uint64 newDay) {
        uint64 today = currentTime / uint64(VaultConstants.DAY);
        if (lastDay != today) {
            newCount = 1;
            newDay = today;
        } else {
            if (todayCount >= VaultConstants.MAX_DAILY_DEPOSITS) {
                revert VaultTypes.DailyDepositLimitReached();
            }
            newCount = todayCount + 1;
            newDay = today;
        }
    }

    function validateStakeLimit(uint256 currentStakes, uint16 personalLimit) internal pure {
        if (currentStakes >= personalLimit) revert VaultTypes.LifetimeStakeLimitReached();
        if (currentStakes >= VaultConstants.MAX_STAKES) revert VaultTypes.LifetimeStakeLimitReached();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // COOLDOWN VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    function validateDepositCooldown(uint64 lastDeposit, uint64 currentTime) internal pure {
        if (lastDeposit > 0 && currentTime < lastDeposit + VaultConstants.DEPOSIT_COOLDOWN) {
            revert VaultTypes.CooldownActive();
        }
    }

    function validateEnrollGrace(uint64 enrolledAt, uint64 currentTime) internal pure {
        if (enrolledAt == 0) revert VaultTypes.NotEnrolled();
        if (currentTime < enrolledAt + VaultConstants.ENROLL_TO_DEPOSIT_GRACE) {
            revert VaultTypes.EnrollGraceNotMet();
        }
    }

    function validateReferrerGrace(uint64 referrerLastDeposit, uint64 currentTime) internal pure {
        if (referrerLastDeposit > 0 && currentTime < referrerLastDeposit + VaultConstants.REFERRER_FRESH_DEPOSIT_GRACE) {
            revert VaultTypes.ReferrerGraceNotMet();
        }
    }

    function validateFirstClaimLock(uint64 firstDepositAt, uint64 currentTime) internal pure {
        if (firstDepositAt == 0) revert VaultTypes.NotEnrolled();
        if (currentTime < firstDepositAt + VaultConstants.FIRST_CLAIM_LOCK) {
            revert VaultTypes.FirstClaimLocked();
        }
    }

    function validateClaimCooldown(uint64 lastClaim, uint64 currentTime) internal pure {
        if (lastClaim > 0 && currentTime < lastClaim + VaultConstants.CLAIM_COOLDOWN) {
            revert VaultTypes.ClaimCooldownActive();
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ENROLLMENT VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    function validateEnrollment(
        bool selfEnrolled,
        bool referrerEnrolled,
        address self,
        address referrer
    ) internal pure {
        if (selfEnrolled) revert VaultTypes.AlreadyEnrolled();
        if (!referrerEnrolled) revert VaultTypes.ReferrerNotEnrolled();
        if (self == referrer) revert VaultTypes.SelfReferral();
        if (referrer == address(0)) revert VaultTypes.ZeroAddress();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // CLAIM VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    function validateMaxWithdraw(uint128 amountUSD) internal pure returns (uint128) {
        if (amountUSD > VaultConstants.MAX_WITHDRAW_USD) {
            return VaultConstants.MAX_WITHDRAW_USD;
        }
        return amountUSD;
    }

    function validateDailyClaimLimit(
        uint64 lastClaimDay,
        uint128 todayClaimed,
        uint128 currentCapUSD,
        uint64 currentTime
    ) internal pure returns (uint64 newDay, uint128 maxAllowed) {
        uint64 today = currentTime / uint64(VaultConstants.DAY);
        uint128 dailyLimit = uint128((uint256(currentCapUSD) *
                                      VaultConstants.DAILY_CLAIM_CAP_BP) /
                                      VaultConstants.PERC_DIVIDER);
        if (lastClaimDay != today) {
            return (today, dailyLimit);
        } else {
            if (todayClaimed >= dailyLimit) revert VaultTypes.DailyClaimLimitReached();
            return (today, dailyLimit - todayClaimed);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // LIQUIDITY VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    function validateLiquidity(uint128 usdtReserve) internal pure {
        if (usdtReserve < VaultConstants.MIN_LIQUIDITY) revert VaultTypes.LiquidityTooLow();
    }

    function validatePostSwapLiquidity(uint128 usdtReserve) internal pure {
        if (usdtReserve < VaultConstants.MIN_LIQUIDITY_POST_SWAP) revert VaultTypes.LiquidityTooLow();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // VAULT BALANCE VALIDATION
    // ═══════════════════════════════════════════════════════════════════════

    function validateVaultBalance(uint256 vaultBalance, uint128 needed) internal pure {
        if (vaultBalance < needed) revert VaultTypes.InsufficientVaultBalance();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // GAS CHECK
    // ═══════════════════════════════════════════════════════════════════════

    function validateGas() internal view {
        if (gasleft() < VaultConstants.MIN_GAS_REQUIRED) revert VaultTypes.InsufficientGas();
    }
}

