        string rankName;
        uint128 reqA;        // Leg A / Leg 1 requirement (USD)
        uint128 reqB;        // Leg B / Leg 2 requirement (USD)
        uint128 reqC;        // Leg 3 requirement (USD) — 0 for salary
        uint128 rewardUSD;   // daily bonus (salary) or total reward (rewards)
        bool achieved;
